import GithubSlugger from "github-slugger";
import fs from "node:fs";
import path from "node:path";
import matter from "gray-matter";
import rehypeRaw from "rehype-raw";
import rehypeSanitize from "rehype-sanitize";
import rehypeSlug from "rehype-slug";
import rehypeStringify from "rehype-stringify";
import remarkGfm from "remark-gfm";
import remarkParse from "remark-parse";
import remarkRehype from "remark-rehype";
import { unified } from "unified";

// The knowledge base archived from the Phrozen Keep. Generated by scripts/keep-import; edit articles in place.

export type KbGroup = "tutorials" | "file-guides" | "reference" | "community";

export interface KbCategory {
  slug: string;
  title: string;
  group: KbGroup;
  /** Legacy Diablo II or Diablo II: Resurrected. */
  game: "legacy" | "d2r";
  /** The Keep's own version label for the category, e.g. "1.10 to 1.14". Not a compatibility claim we've checked. */
  appliesTo?: string;
  description?: string;
  keepId: number;
  keepName: string;
}

export interface KbArticle {
  category: string;
  slug: string;
  href: string;
  /** Plain markdown for language models and tools. */
  markdownHref: string;
  file: string;
  title: string;
  summary: string;
  keepId: number;
  /** The account that posted the article on the Keep. */
  author?: string;
  /** Credits from the Keep's description field, e.g. "by Nefarius, restyled by HarvestWombs". */
  credit?: string;
  posted?: string;
  modified?: string;
  views?: number;
  originalUrl: string;
  body: string;
}

export const KB_GROUPS: Record<KbGroup, { label: string; lead: string }> = {
  "file-guides": {
    label: "File guides",
    lead: "Column by column guides to the game's data files.",
  },
  tutorials: {
    label: "Tutorials",
    lead: "Step by step guides for specific changes, grouped by the game version they were written for.",
  },
  reference: {
    label: "Reference",
    lead: "Charts, mechanics, file formats and DLL research.",
  },
  community: {
    label: "From the Keep",
    lead: "Interviews, reviews, FAQs and site news from 2000 onward.",
  },
};

const KB_DIR = path.join(process.cwd(), "content/kb");

let categoriesCache: KbCategory[] | undefined;
let articlesCache: KbArticle[] | undefined;
const fresh = () => process.env.NODE_ENV !== "production";

export function getKbCategories(): KbCategory[] {
  if (categoriesCache && !fresh()) return categoriesCache;
  const file = path.join(KB_DIR, "categories.json");
  categoriesCache = fs.existsSync(file) ? (JSON.parse(fs.readFileSync(file, "utf8")) as KbCategory[]) : [];
  return categoriesCache;
}

export function getKbCategory(slug: string) {
  return getKbCategories().find((c) => c.slug === slug);
}

const asDate = (v: unknown) => (v instanceof Date ? v.toISOString().slice(0, 10) : (v as string | undefined));

export function getKbArticles(category?: string): KbArticle[] {
  if (!articlesCache || fresh()) {
    articlesCache = getKbCategories().flatMap((c) => {
      const dir = path.join(KB_DIR, c.slug);
      if (!fs.existsSync(dir)) return [];
      return fs
        .readdirSync(dir)
        .filter((f) => f.endsWith(".md"))
        .map((f) => {
          const slug = f.replace(/\.md$/, "");
          const { data, content } = matter(fs.readFileSync(path.join(dir, f), "utf8"));
          return {
            ...(data as Omit<KbArticle, "category" | "slug" | "href" | "markdownHref" | "file" | "body">),
            posted: asDate(data.posted),
            modified: asDate(data.modified),
            category: c.slug,
            slug,
            href: `/kb/${c.slug}/${slug}`,
            markdownHref: `/api/kb/${c.slug}/${slug}`,
            file: `content/kb/${c.slug}/${f}`,
            body: content,
          } satisfies KbArticle;
        })
        .sort((a, b) => a.title.localeCompare(b.title, "en", { sensitivity: "base" }));
    });
  }
  return category ? articlesCache.filter((a) => a.category === category) : articlesCache;
}

export function getKbArticle(category: string, slug: string) {
  return getKbArticles(category).find((a) => a.slug === slug);
}

/** Articles that have an equivalent page on the data file list, matched by file name. */
export function findFileGuide(fileName: string) {
  const want = fileName.toLowerCase();
  return getKbArticles("file-guides")
    .filter((a) => a.title.toLowerCase().startsWith(want))
    .sort((a, b) => (b.views ?? 0) - (a.views ?? 0))[0];
}

const processor = unified()
  .use(remarkParse)
  .use(remarkGfm)
  .use(remarkRehype, { allowDangerousHtml: true })
  .use(rehypeRaw)
  .use(rehypeSanitize)
  .use(rehypeSlug)
  .use(rehypeStringify);

const CALLOUT_KIND: Record<string, string> = { Warning: "warning", Caution: "warning", Important: "warning", Note: "note", Tip: "tip" };

/** Archived articles are plain markdown with some leftover HTML, so they skip MDX and get sanitised instead. */
export async function renderKbMarkdown(body: string) {
  const html = String(await processor.process(body));
  // tidy-kb.ts writes the Keep's warning and note icons as "> **Warning:** ..." quotes.
  return html.replace(
    /<blockquote>\s*<p><strong>(Warning|Caution|Important|Note|Tip):<\/strong>\s*([\s\S]*?)<\/blockquote>/g,
    (_, label: string, rest: string) =>
      `<div class="kb-callout kb-callout-${CALLOUT_KIND[label]}"><p class="kb-callout-label">${label}</p><p>${rest}</div>`,
  );
}

/** Level-two headings, with the same ids rehype-slug gives them. */
export function kbToc(body: string) {
  const slugger = new GithubSlugger();
  const out: { text: string; id: string }[] = [];
  for (const m of body.matchAll(/^(#{1,6})\s+(.+)$/gm)) {
    const text = m[2].replace(/\\(.)/g, "$1").replace(/[`*_]/g, "").trim();
    const id = slugger.slug(text);
    if (m[1] === "##") out.push({ text, id });
  }
  return out;
}

/** One article as a standalone markdown document, with its provenance up front. */
export function kbArticleMarkdown(a: KbArticle, siteUrl: string) {
  const cat = getKbCategory(a.category);
  const lines = [
    `# ${a.title}`,
    "",
    `- Source: ${siteUrl}${a.href}`,
    `- Archived from: ${a.originalUrl}`,
    cat && `- Category: ${cat.title}${cat.game === "d2r" ? " (Diablo II: Resurrected)" : ""}`,
    cat?.appliesTo && `- Game version, as labelled on the Keep: ${cat.appliesTo}`,
    a.author && `- Posted by: ${a.author}`,
    a.credit && `- Credits: ${a.credit}`,
    a.posted && `- Posted: ${a.posted}`,
    a.modified && `- Last edited: ${a.modified}`,
    "",
    a.body.trim(),
    "",
  ];
  return lines.filter((l): l is string => typeof l === "string").join("\n");
}
